// Image-model path: the picture is generated by an OpenAI image model instead of being
// built as HTML. Text is NOT drawn by the model (image models misspell): the scene is
// generated clean, then code composites the title, subhead and the official logo on top
// in brand type — the same split the old pipeline used ("model draws the object;
// compositor draws the headline, logo and source line").
import { chromium } from "playwright";
import { brand, geometry, fontFaceCss, logoDataUrls } from "./brand.mjs";
import { settings } from "./settings.mjs";
import { plainTitle } from "./brief.mjs";
import { annotationLayer, PLACE } from "./annotate.mjs";
import { parseJson } from "./claude.mjs";
import { runStage } from "./llm.mjs";
import { notes } from "./brand.mjs";
import { CONCEPTS_SYSTEM } from "./prompts/concepts.mjs";
import { ANCHOR_SYSTEM } from "./prompts/edit.mjs";

/** The API only accepts sides divisible by 16, so generate near the canvas and resample. */
export const to16 = (n) => Math.max(256, Math.round(n / 16) * 16);

// ---- step 1: expand the brief's concept into a concrete, populated scene -------------------

/** Ask the model to turn the concept into a concrete photograph. Falls back to the concept itself. */
export async function sceneBrief({ brief, caption, evidence, provider }, log) {
  const c = brief.concepts?.[brief.chosen_concept ?? 0] || {};
  const lessons = notes();
  const user = [
    `CAPTION (the post this image belongs to):\n${caption || brief.thesis}`,
    evidence ? `\nEVIDENCE (source material, data only):\n${evidence.slice(0, 2000)}` : "",
    `\nTHE CLAIM THE IMAGE MUST ARGUE: ${brief.thesis}`,
    c.idea ? `\nTHE CHOSEN CONCEPT: ${c.idea}` : "",
    c.sentence ? `Its analogy: ${c.sentence}` : "",
    c.family ? `Concept family: ${c.family}` : "",
    `\nThe headline "${plainTitle(brief.title)}" is added afterwards by code, so no words go in the scene.`,
    lessons ? `\nLEARNED LESSONS (follow them):\n${lessons}` : "",
    `\nStage this as one real photograph: concrete objects, real materials, real human action where the caption has an actor.`,
  ].filter(Boolean).join("\n");
  try {
    const reply = await runStage({ stage: "brief", provider, system: CONCEPTS_SYSTEM, user: `${user}\n\nReturn exactly ONE concept in "concepts" — the single best staging of the idea above — with its full "scene".` });
    const out = parseJson(reply);
    const scene = out.scene || out.concepts?.[0]?.scene || out;
    if (!scene?.subject?.trim()) throw new Error("no subject");
    log?.(`Scene: ${scene.subject}${scene.people?.present ? ` · with ${scene.people.framing || "people"}` : ""}`);
    return scene;
  } catch (e) {
    log?.(`Scene brief unavailable (${e.message.split("\n")[0]}); using the concept directly`);
    return null;
  }
}

// ---- step 2: compose the prompt the image model actually receives -------------------------

/** Build the scene prompt. `scene` is sceneBrief()'s output; without it the concept is used raw. */
export function scenePrompt(b, width, height, scene = null) {
  const c = b.concepts?.[b.chosen_concept ?? 0] || {};
  // brief fields sometimes already end in a full stop: never double it
  const t = (x = "") => String(x).trim().replace(/[.\s]+$/, "");
  const portrait = height > width * 1.1;
  const zone = portrait ? "the bottom third of the frame" : "the left 40% of the frame";
  const subjectSide = portrait ? "the upper two thirds" : "the right 55-60%";
  const out = [];

  if (scene) {
    out.push(`A single premium editorial photograph for an AI-research audience: ${t(scene.subject)}.`);
    // the storytelling approach decides HOW the picture argues; it must reach the image model
    const approach = b.approach || scene.approach || b.strategy || scene.strategy;
    const how = {
      symbolic_comparison:
        "Composition is a direct comparison: show the two things side by side as the SAME kind of object, in the SAME setting, under the SAME light, at the SAME scale, shot from the SAME angle, with the SAME background behind both. Exactly ONE property differs between them, and that difference is the entire point — nothing else may vary. Do not put one on a plain backdrop and the other in a scene.",
      conceptual_infographic:
        "Composition reveals structure: show the layers, stages or parts in one frame so their relationship is legible at a glance — what sits above what, what is hidden beneath what, what connects to what. The arrangement itself carries the argument.",
      visual_narrative:
        "Composition shows progression: the stages must be visible together and read in order across the frame, so the viewer sees the journey and where it has got to, not a single frozen moment.",
      physical_analogy:
        "Composition is one real object or setting doing the thing it really does. Shoot it honestly and close enough to read its materials and wear; its ordinary behaviour is the argument.",
      technical_visualization:
        "Composition shows the mechanism working: the parts, the direction of travel between them, and the loop or dependency that matters. Keep it legible and physical — never decorative technical noise.",
      // older strategy vocabulary, still accepted
      object_study: "Show one revealing object close and whole — cut open, worn or dismantled — so its inside explains its outside.",
      comparison: "Place the specimens side by side in identical conditions so the single difference between them is unmistakable.",
      structure: "Show how the parts hold each other up: the load path and the connections must read clearly.",
      transformation: "Show the same material at its successive stages, in order, in one frame.",
      cause_effect: "Show the force and the mark it has left, both in frame, so the consequence is legible.",
      scale_shift: "Shoot at the scale that reveals the hidden order — macro detail or a distant overview.",
    }[approach];
    if (how) out.push(how);
    // A scene that stages two of the same kind of thing IS a comparison, whatever it was labelled.
    // Without this the model varies the background too, and the viewer cannot tell what the point is.
    const objs0 = (scene.objects || []).filter((o) => o?.what);
    const headWord = (x) => (x.what || "").toLowerCase().replace(/[^a-z ]/g, "").split(/\s+/).filter((w) => w.length > 3).pop() || "";
    const pairs = {};
    for (const o of objs0) { const k = headWord(o); if (k) (pairs[k] ||= []).push(o); }
    const twin = Object.values(pairs).find((g) => g.length === 2);
    if (twin && approach !== "symbolic_comparison")
      out.push(
        `This frame holds two of the same kind of thing (${twin[0].what} and ${twin[1].what}), so it reads as a comparison: ` +
          `give them the SAME setting, the SAME background, the SAME light and the SAME framing, at the same scale and angle. ` +
          `Only the one property being contrasted may differ between them, and BOTH must be equally visible and equally well lit — ` +
          `do not leave one in shadow, cropped or pushed behind the other.`
      );
    if (b.how_it_communicates) out.push(`What the composition must deliver: ${t(b.how_it_communicates)}.`);
    if ((b.mapping || []).length)
      out.push(
        `Each element must remain recognisable as what it stands for: ` +
          b.mapping.map((m) => `${m.element} = ${m.represents}`).join("; ") + `.`
      );
    if (scene.action) out.push(`The moment: ${t(scene.action)}.`);
    if (scene.setting) out.push(`Setting: ${t(scene.setting)}.`);
    const objs = (scene.objects || []).filter((o) => o?.what);
    if (objs.length)
      out.push(
        `Make these real objects clearly visible, distinct and believable: ` +
        objs.map((o) => `${o.what}${o.material ? ` in ${o.material}` : ""}${o.where ? `, ${o.where}` : ""}`).join("; ") + `.`
      );
    if (scene.people?.present) {
      const pp = scene.people;
      out.push(
        `Human presence: ${t(pp.who) || "a person"}, ${t(pp.doing) || "at work"}. Framing: ${t(pp.framing) || "hands and forearms only"}. ` +
        `Real skin, real hands with correct anatomy, natural posture, clothing with real fabric and wear. ` +
        `The face is turned away, cropped or softly out of focus — never a posed portrait looking at the camera, never a stock-photo smile.`
      );
    } else {
      out.push(`No people, no hands and no figures anywhere in the frame: the objects alone carry the meaning.`);
    }
    // the parts must be separable, because short labels are composited onto them afterwards
    const calls = (scene.callouts || []).filter((c) => c?.label);
    if (calls.length)
      out.push(
        `Keep these parts clearly visible, separated and distinctly lit so each can be pointed at, with clear uncluttered space beside it: ` +
        calls.map((c) => `${t(c.points_at) || t(c.label)} (about ${Math.round(c.x)}% across, ${Math.round(c.y)}% down)`).join("; ") + `.`
      );
    if (scene.focal_point) out.push(`Focal point, sharpest and best lit: ${t(scene.focal_point)}.`);
    if (scene.depth) out.push(`Depth: ${t(scene.depth)}.`);
    if (scene.light) out.push(`Light: ${t(scene.light)}.`);
    if (scene.camera) out.push(`Camera: ${t(scene.camera)}.`);
  } else {
    out.push(`A single premium editorial photograph for an AI-research audience: ${t(c.idea || b.rationale || b.thesis)}.`);
    if (c.sentence) out.push(`The idea: ${t(c.sentence)}.`);
    out.push(`Stage it with real objects and real materials in a real place, and show human action through hands at work where the claim has an actor.`);
    out.push(`Light: directional, physically plausible, with real shadow falloff. Camera: 50mm feel, slight low angle, close enough to read the materials.`);
  }

  out.push(`It must argue one claim at a glance: ${t(b.thesis)}.`);
  out.push(
    `Finish: photorealistic, a real photograph — genuine materials (metal, wood, glass, paper, fabric, skin), physically plausible light and shadow, believable reflections, natural micro-detail, fine grain, shallow depth of field with the focal point sharp. ` +
    `A premium research-lab, workshop or consultancy photograph. Not a CGI render, not a 3D illustration, not an AI poster, not clip-art, not a stock photo.`
  );
  out.push(
    `Colour: a near-black ground (#0B0E14 to #121724) with restrained greys and the true colours of the real materials, and Ethara purple (#8B2CF5 / #A855F7) ONLY as a subtle rim light or single accent on the focal point. No other saturated colour anywhere.`
  );
  out.push(
    `Composition: the subject fills ${subjectSide}; keep ${zone} as clean, uncluttered, low-detail, near-black negative space for a headline that is added afterwards, and keep the top-left corner plain and empty for a logo. Nothing important may sit in those reserved areas.`
  );
  out.push(
    `Draw NO text, letters, numbers, words, labels, captions, signage, UI, dashboards, charts, graphs, printed pages, watermarks or logos anywhere in the image — every word is composited afterwards by code.`
  );
  out.push(
    `Avoid these entirely: glowing brain, humanoid robot or android, light bulb, rocket, circuit board, binary code, padlock-and-shield, floating holograms, neon grids, data streams, swirling glowing particles, lens flare, and any screen or interface.`
  );
  out.push(`Size: ${width}×${height}.`);
  return out.join(" ");
}

/** Call the image model. Returns a base64 PNG. */
export async function runImageModel({ prompt, width, height, timeoutS = 300 }) {
  const cfg = settings().openai;
  if (!cfg.apiKey) throw new Error("No OpenAI API key set (add OPENAI_API_KEY to .env).");
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutS * 1000);
  try {
    const res = await fetch(`${cfg.baseUrl}/images/generations`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${cfg.apiKey}` },
      body: JSON.stringify({ model: cfg.imageModel, prompt, size: `${to16(width)}x${to16(height)}`, n: 1 }),
      signal: ctrl.signal,
    });
    const text = await res.text();
    if (!res.ok) {
      let msg = text.slice(0, 400);
      try { msg = JSON.parse(text).error?.message || msg; } catch { /* keep raw */ }
      throw new Error(`OpenAI images ${res.status}: ${msg}`);
    }
    const b64 = JSON.parse(text).data?.[0]?.b64_json;
    if (!b64) throw new Error("The image model returned no image data");
    return b64;
  } catch (e) {
    if (e.name === "AbortError") throw new Error(`Image model timed out after ${timeoutS}s`);
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Anchors are planned before the picture exists, so they are guesses. Once the image is made,
 * look at it and move each label to where its element actually is. Returns a patched brief.
 */
export async function resolveAnchors({ b, platePath, provider }, log = () => {}) {
  const calls = (b.annotation?.callouts || []).filter((c) => c?.label);
  if (!calls.length || b.annotation?.style === "editorial_only") return b;
  const user = [
    `IMAGE FILE: ${platePath}`,
    `\nTHE ELEMENTS LABELS MUST POINT AT:`,
    ...calls.map((c) => `- "${c.points_at || c.label}"  (label reads "${c.label}"; it was planned for ${Math.round(c.x)}%, ${Math.round(c.y)}% — verify or correct)`),
  ].join("\n");
  try {
    const reply = await runStage({ stage: "qa", provider, system: ANCHOR_SYSTEM, user, imagePath: platePath });
    const out = parseJson(reply);
    const found = out.elements || [];
    const next = structuredClone(b);
    let moved = 0, dropped = 0;
    next.annotation.callouts = calls
      .map((c) => {
        const hit = found.find((f) => (f.points_at || "").toLowerCase().trim() === (c.points_at || c.label).toLowerCase().trim()) || found.shift();
        if (!hit || hit.found === false) { dropped++; return null; }
        if (!Number.isFinite(hit.x) || !Number.isFinite(hit.y)) return c;
        const dx = Math.abs(hit.x - c.x), dy = Math.abs(hit.y - c.y);
        if (dx > 1.5 || dy > 1.5) moved++;
        return { ...c, x: Math.max(3, Math.min(95, hit.x)), y: Math.max(3, Math.min(95, hit.y)), sawAt: hit.what_you_see || "", confidence: hit.confidence || "" };
      })
      .filter(Boolean);
    if (out.clear_areas?.length) next.annotation.clear_areas = out.clear_areas;
    log(
      `Anchors: ${moved} label${moved === 1 ? "" : "s"} moved onto the real element` +
        (dropped ? `, ${dropped} dropped (element not in the picture)` : "")
    );
    return next;
  } catch (e) {
    log(`Anchors: could not be checked (${e.message.split("\n")[0]}); using the planned positions`);
    return b;
  }
}

/** Compose: generated scene as the ground, brand type and the official logo on top. */
export async function composeScene({ b, pngB64, width, height, quality, jpgPath }) {
  const g = geometry(width, height);
  const layer = annotationLayer(b, width, height);

  const html = `<!doctype html><html><head><meta charset="utf-8"><style>${fontFaceCss()}
html,body{margin:0;padding:0;width:${width}px;height:${height}px;overflow:hidden;background:#0B0E14}
.bg{position:absolute;inset:0;width:${width}px;height:${height}px;object-fit:cover}
${layer.css}
</style></head><body>
<img class="bg" src="data:image/png;base64,${pngB64}">
${layer.html}
</body></html>`;

  const browser = await chromium.launch();
  try {
    const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 2, offline: true });
    const p = await ctx.newPage();
    await p.route("**/*", (r) => (r.request().url().startsWith("data:") ? r.continue() : r.abort()));
    await p.setContent(html, { waitUntil: "load" });
    await p.evaluate(() => document.fonts.ready.then(() => true));

    // resolve collisions on the rendered page, then read back what is actually drawn
    const placed = await p.evaluate(PLACE, [layer.headlineRect, g.margin, width, height]);

    const logos = logoDataUrls();
    const ratio = await p.evaluate(async (src) => { const i = new Image(); i.src = src; await i.decode(); return i.width / i.height; }, logos.onDark);
    const box = { x: g.logoOffset, y: g.logoOffset, width: Math.round(ratio * g.logoH), height: g.logoH };
    await p.evaluate(async ({ src, x, y, h }) => {
      const img = document.createElement("img");
      img.src = src;
      img.style.cssText = `position:fixed;left:${x}px;top:${y}px;height:${h}px;width:auto;z-index:2147483647;`;
      document.body.appendChild(img);
      await img.decode();
    }, { src: logos.onDark, x: box.x, y: box.y, h: g.logoH });

    const problems = overlayProblems(b, placed, layer, width, height);

    const shot = await p.screenshot({ type: "png", clip: { x: 0, y: 0, width, height } });
    const exp = await browser.newPage();
    const jpg = await exp.evaluate(async ({ src, w, h, q }) => {
      const img = new Image(); img.src = src; await img.decode();
      const c = document.createElement("canvas"); c.width = w; c.height = h;
      const cx = c.getContext("2d"); cx.imageSmoothingEnabled = true; cx.imageSmoothingQuality = "high";
      cx.drawImage(img, 0, 0, w, h);
      return c.toDataURL("image/jpeg", q).split(",")[1];
    }, { src: "data:image/png;base64," + shot.toString("base64"), w: width, h: height, q: quality / 100 });
    const { writeFile } = await import("node:fs/promises");
    await writeFile(jpgPath, Buffer.from(jpg, "base64"));
    if (layer.dropped?.length)
      for (const d of layer.dropped) problems.push(`Annotation removed before rendering — "${d.label}": ${d.why}`);
    return {
      problems,
      logoVariant: "light-text (dark ground)",
      pixels: `${width}×${height}`,
      overlay: {
        style: layer.style,
        zone: layer.zone,
        labels: placed.map((x) => x.text),
        dropped: layer.dropped || [],
      },
    };
  } finally {
    await browser.close();
  }
}

/** Code-side overlay checks: spelling, placement and legibility of what code drew. */
function overlayProblems(b, placed, layer, width, height) {
  const out = [];
  const wanted = (b.annotation?.callouts || []).map((c) => String(c.label || "").trim()).filter(Boolean);
  const drawn = placed.map((p) => p.text).filter(Boolean);
  // spelling: drawn text must equal the brief's string exactly, since code copied it
  for (const w of wanted) {
    if (layer.style === "editorial_only" || layer.style === "numbered_steps") continue;
    if (!drawn.some((d) => d.toLowerCase() === w.toLowerCase()))
      out.push(`Callout "${w}" did not render as written (drawn: ${drawn.join(", ") || "none"})`);
  }
  const M = Math.round(Math.min(width, height) * brand.logo.margin_share);
  for (const p of placed) {
    if (p.left < M - 1 || p.top < M - 1 || p.right > width - M + 1 || p.bottom > height - M + 1)
      out.push(`Label "${p.text}" sits outside the margin after placement; shorten it or move its anchor`);
  }
  for (let i = 0; i < placed.length; i++)
    for (let j = i + 1; j < placed.length; j++) {
      const a = placed[i], c = placed[j];
      if (a.left < c.right && c.left < a.right && a.top < c.bottom && c.top < a.bottom)
        out.push(`Labels "${a.text}" and "${c.text}" overlap`);
    }
  return out;
}

/** The design-stage replacement when the image model is in charge. */
export async function designByImageModel(b, opts, log) {
  // the brief already carries the scene for concept_metaphor; only expand when it doesn't
  let scene = b.scene || null;
  if (scene?.subject) log(`Scene (from the brief): ${scene.subject}`);
  else {
    log("Scene: turning the concept into a real photograph…");
    scene = await sceneBrief({ brief: b, caption: opts.caption, evidence: opts.evidence, provider: opts.provider }, log);
  }
  const prompt = scenePrompt(b, opts.width, opts.height, scene);
  log(`Image model: generating the scene with ${settings().openai.imageModel} at ${to16(opts.width)}×${to16(opts.height)}…`);
  const pngB64 = await runImageModel({ prompt, width: opts.width, height: opts.height, timeoutS: brand.models.design.timeout_s });
  // the wordless plate is kept so a later edit can change the PHOTOGRAPH, not the composited type
  const platePath = opts.jpgPath.replace(/\.jpg$/, ".scene.png");
  const { writeFile } = await import("node:fs/promises");
  await writeFile(platePath, Buffer.from(pngB64, "base64"));

  // pin the labels to what the image actually contains, before any of them are drawn
  const pinned = await resolveAnchors({ b, platePath, provider: opts.provider }, log);

  log("Compositing the headline and the official logo…");
  const r = await composeScene({ b: pinned, pngB64, width: opts.width, height: opts.height, quality: opts.quality, jpgPath: opts.jpgPath });
  return { ...r, plate: platePath, brief: pinned, design: { mode: "image", prompt, scene, model: settings().openai.imageModel } };
}
